package com.primehr.rsp.handoff.api;
import com.primehr.rsp.handoff.application.AppointmentHandoffService;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController public class AppointmentHandoffController{private final AppointmentHandoffService service;private final RspAppointmentHandoffPermissionGuard permission;private final AgencyScopeResolver agency;public AppointmentHandoffController(AppointmentHandoffService s,RspAppointmentHandoffPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}@PostMapping("/api/primehr/v1/rsp/selection-cases/{selectionId}/appointment-handoffs")@ResponseStatus(HttpStatus.CREATED)public AppointmentHandoffDtos.Response create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String selectionId){permission.require(PrimeHrAction.ADD,token);return service.create(agency.resolveAgencyId(a),selectionId,a.getName(),correlation);}@GetMapping("/api/primehr/v1/rsp/appointment-handoffs/{id}")public AppointmentHandoffDtos.Response get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id){permission.require(PrimeHrAction.ACCESS,token);return service.get(agency.resolveAgencyId(a),id);}@PostMapping("/api/primehr/v1/rsp/appointment-handoffs/{id}/{action:submit|retry|reconcile}")public AppointmentHandoffDtos.Response deliver(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@PathVariable String id,@PathVariable String action,@Valid @RequestBody AppointmentHandoffDtos.Command command){permission.require(action.equals("reconcile")?PrimeHrAction.FINALIZE:PrimeHrAction.SUBMIT,token);return service.deliver(agency.resolveAgencyId(a),id,command.recordVersion(),a.getName(),action);}}
